--
-- Table structure for table `club_class_enrollments`
--

DROP TABLE IF EXISTS `club_class_enrollments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `club_class_enrollments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `class_id` int NOT NULL,
  `member_id` int NOT NULL,
  `enrollment_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attendance_status` enum('registered','attended','absent','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'registered',
  `attendance_time` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `club_class_enrollments_class_id_member_id_key` (`class_id`,`member_id`),
  KEY `club_class_enrollments_member_id_idx` (`member_id`),
  CONSTRAINT `club_class_enrollments_class_id_fkey` FOREIGN KEY (`class_id`) REFERENCES `club_classes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

