INSERT INTO `club_content_items` VALUES (1,'announcement','افتتاح قسم الكروس فيت الجديد','يسر النادي الإعلان عن افتتاح قسم الكروس فيت المجهز بأحدث الأجهزة.',NULL,1,1,NULL,1,0,'2026-07-04 23:51:36.569','2026-07-04 23:51:36.569'),(2,'announcement','عرض الصيف: خصم 20% على السنوي','استمتع بخصم 20% على الاشتراك السنوي حتى نهاية الشهر.',NULL,2,1,NULL,NULL,0,'2026-07-04 23:51:36.569','2026-07-04 23:51:36.569'),(3,'announcement','جدول حصص رمضان','تم تحديث جدول الحصص ليتناسب مع أوقات الشهر الكريم.',NULL,3,1,NULL,1,0,'2026-07-04 23:51:36.570','2026-07-04 23:51:36.570'),(4,'announcement','صيانة المسبح','سيتم إغلاق المسبح للصيانة الدورية يوم الجمعة.',NULL,4,1,NULL,1,0,'2026-07-04 23:51:36.570','2026-07-04 23:51:36.570'),(5,'faq','كيف يمكنني تجميد اشتراكي؟','يمكنك طلب التجميد من خلال الاستقبال أو التطبيق، بحد أقصى 14 يوماً للباقات السنوية.',NULL,1,1,NULL,1,0,'2026-07-04 23:51:36.570','2026-07-04 23:51:36.570'),(6,'faq','ما هي مواعيد قسم السيدات؟','قسم السيدات مفتوح يومياً من 8 صباحاً حتى 10 مساءً.',NULL,2,1,NULL,NULL,0,'2026-07-04 23:51:36.571','2026-07-04 23:51:36.571'),(7,'faq','هل تتوفر حصص تدريب شخصي؟','نعم، تتوفر باقات حصص تدريب شخصي مع مدربين معتمدين.',NULL,3,1,NULL,1,0,'2026-07-04 23:51:36.571','2026-07-04 23:51:36.571'),(8,'faq','كيف أحجز موعد إن بودي؟','عبر التطبيق أو الاستقبال، والخدمة مجانية للأعضاء الجدد.',NULL,4,1,NULL,NULL,0,'2026-07-04 23:51:36.571','2026-07-04 23:51:36.571'),(9,'exercise','تمرين السكوات','تمرين أساسي لعضلات الأرجل، 4 مجموعات × 12 تكرار.',NULL,1,1,NULL,NULL,0,'2026-07-04 23:51:36.572','2026-07-04 23:51:36.572'),(10,'exercise','تمرين الضغط','لتقوية الصدر والكتف، 3 مجموعات حتى الإجهاد.',NULL,2,1,NULL,1,0,'2026-07-04 23:51:36.572','2026-07-04 23:51:36.572'),(11,'exercise','العقلة','لعضلات الظهر والذراعين، 3 مجموعات × 8 تكرار.',NULL,3,1,NULL,1,0,'2026-07-04 23:51:36.572','2026-07-04 23:51:36.572'),(12,'exercise','الرفعة الميتة','تمرين مركّب لكامل الجسم، ركّز على وضعية الظهر.',NULL,4,1,NULL,NULL,0,'2026-07-04 23:51:36.573','2026-07-04 23:51:36.573'),(1