--
-- Table structure for table `club_subscriptions`
--

DROP TABLE IF EXISTS `club_subscriptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `club_subscriptions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `subscription_number` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `branch_id` int NOT NULL,
  `member_id` int DEFAULT NULL,
  `customer_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subscription_type_id` int DEFAULT NULL,
  `subscription_type` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subscription_start_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subscription_end_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subscription_value` decimal(10,2) NOT NULL,
  `discount_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `discount_value` decimal(10,2) NOT NULL DEFAULT '0.00',
  `paid_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `remaining_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `gender` enum('male','female') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `employee_id` int DEFAULT NULL,
  `sales_id` int DEFAULT NULL,
  `payment_method` enum('cash','card','bank','online','visa','transfer','wallet') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receipt_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','expired','upcoming','frozen') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `is_special` tinyint(1) NOT NULL DEFAULT '0',
  `is_linked_to_sessions` tinyint(1) NOT NULL DEFAULT '0',
  `sessions_count` int DEFAULT NULL,
  `sessions_used` int NOT NULL DEFAULT '0',
  `is_time_based` tinyint(1) NOT NULL DEFAULT '0',
  `time_from` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `time_to` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  `customer_source_id` int DEFAULT NULL,
  `guardian_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guardian_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `club_subscriptions_subscription_number_key` (`subscription_number`),
  KEY `club_subscriptions_member_id_idx` (`member_id`),
  KEY `club_subscriptions_branch_id_idx` (`branch_id`),
  KEY `club_subscriptions_status_idx` (`status`),
  KEY `club_subscriptions_subscription_type_id_fkey` (`subscription_type_id`),
  CONSTRAINT `club_subscriptions_member_id_fkey` FOREIGN KEY (`member_id`) REFERENCES `club_members` (`id`),
  CONSTRAINT `club_subscriptions_subscription_type_id_fkey` FOREIGN KEY (`subscription_type_id`) REFERENCES `club_subscription_types` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

