DROP TABLE IF EXISTS `inv_opening_stocks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inv_opening_stocks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `opening_stock_date` datetime(3) DEFAULT NULL,
  `item_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(14,3) NOT NULL,
  `unit_cost` decimal(12,2) NOT NULL,
  `total_cost` decimal(14,2) NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `branch_id` int NOT NULL,
  `warehouse_id` int NOT NULL,
  `product_id` int DEFAULT NULL,
  `spare_part_id` int DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `inv_opening_stocks_branch_id_idx` (`branch_id`),
  KEY `inv_opening_stocks_warehouse_id_idx` (`warehouse_id`),
  KEY `inv_opening_stocks_product_id_idx` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
