DROP TABLE IF EXISTS `inv_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inv_products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `barcode` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `brand_id` int DEFAULT NULL,
  `manufacturer_id` int DEFAULT NULL,
  `supplier_id` int DEFAULT NULL,
  `cost_price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `selling_price` decimal(12,2) NOT NULL,
  `wholesale_price` decimal(12,2) DEFAULT NULL,
  `unit_of_measure` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'وحدة',
  `unit_template_id` int DEFAULT NULL,
  `min_stock` int NOT NULL DEFAULT '1',
  `max_stock` int NOT NULL DEFAULT '1000',
  `reorder_point` int NOT NULL DEFAULT '10',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `material` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight_kg` decimal(10,3) DEFAULT NULL,
  `dimensions` json DEFAULT NULL,
  `warranty_period` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expiry_date` datetime(3) DEFAULT NULL,
  `batch_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shelf_location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apply_to_all_branches` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inv_products_product_code_key` (`product_code`),
  UNIQUE KEY `inv_products_barcode_key` (`barcode`),
  KEY `inv_products_category_id_idx` (`category_id`),
  KEY `inv_products_brand_id_idx` (`brand_id`),
  KEY `inv_products_supplier_id_idx` (`supplier_id`),
  KEY `inv_products_status_idx` (`status`),
  KEY `inv_products_manufacturer_id_fkey` (`manufacturer_id`),
  KEY `inv_products_unit_template_id_fkey` (`unit_template_id`),
  CONSTRAINT `inv_products_brand_id_fkey` FOREIGN KEY (`brand_id`) REFERENCES `inv_brands` (`id`),
  CONSTRAINT `inv_products_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `inv_categories` (`id`),
  CONSTRAINT `inv_products_manufacturer_id_fkey` FOREIGN KEY (`manufacturer_id`) REFERENCES `inv_manufacturers` (`id`),
  CONSTRAINT `inv_products_supplier_id_fkey` FOREIGN KEY (`supplier_id`) REFERENCES `inv_suppliers` (`id`),
  CONSTRAINT `inv_products_unit_template_id_fkey` FOREIGN KEY (`unit_template_id`) REFERENCES `inv_unit_templates` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
