--
-- Table structure for table `rbac_resources`
--

DROP TABLE IF EXISTS `rbac_resources`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rbac_resources` (
  `id` int NOT NULL AUTO_INCREMENT,
  `key` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_id` int DEFAULT NULL,
  `type` enum('module','group','page') COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `route` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `rbac_resources_key_key` (`key`),
  KEY `rbac_resources_parent_id_idx` (`parent_id`),
  CONSTRAINT `rbac_resources_parent_id_fkey` FOREIGN KEY (`parent_id`) REFERENCES `rbac_resources` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

