  CONSTRAINT `rbac_role_permissions_resource_id_fkey` FOREIGN KEY (`resource_id`) REFERENCES `rbac_resources` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rbac_role_permissions_role_id_fkey` FOREIGN KEY (`role_id`) REFERENCES `rbac_roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
