CREATE TABLE `rbac_role_scopes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `role_id` int NOT NULL,
  `resource_id` int NOT NULL,
  `scope` enum('own','team','branch','department','global') COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rbac_role_scopes_role_id_resource_id_key` (`role_id`,`resource_id`),
  KEY `rbac_role_scopes_role_id_idx` (`role_id`),
  KEY `rbac_role_scopes_resource_id_fkey` (`resource_id`),
  CONSTRAINT `rbac_role_scopes_resource_id_fkey` FOREIGN KEY (`resource_id`) REFERENCES `rbac_resources` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rbac_role_scopes_role_id_fkey` FOREIGN KEY (`role_id`) REFERENCES `rbac_roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
