DROP TABLE IF EXISTS `sales_quick_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_quick_sales` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sale_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'عميل نقدي',
  `customer_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch_id` int NOT NULL,
  `cashier_id` int DEFAULT NULL,
  `shift_session_id` int DEFAULT NULL,
  `sale_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sale_time` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtotal` decimal(10,2) NOT NULL,
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount_percentage` decimal(5,2) NOT NULL DEFAULT '0.00',
  `tax_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tax_percentage` decimal(5,2) NOT NULL DEFAULT '15.00',
  `total_amount` decimal(10,2) NOT NULL,
  `payment_method` enum('cash','card','wallet','transfer','mixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cash',
  `status` enum('completed','refunded','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'completed',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `loyalty_points_earned` int NOT NULL DEFAULT '0',
  `receipt_printed` tinyint(1) NOT NULL DEFAULT '0',
  `warehouse_id` int DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sales_quick_sales_sale_number_key` (`sale_number`),
  KEY `sales_quick_sales_branch_id_idx` (`branch_id`),
  KEY `sales_quick_sales_sale_date_idx` (`sale_date`),
  KEY `sales_quick_sales_status_idx` (`status`),
  KEY `sales_quick_sales_shift_session_id_idx` (`shift_session_id`),
  KEY `sales_quick_sales_cashier_id_idx` (`cashier_id`),
  CONSTRAINT `sales_quick_sales_shift_session_id_fkey` FOREIGN KEY (`shift_session_id`) REFERENCES `sales_shift_sessions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

