--
-- Table structure for table `sales_shift_sessions`
--

DROP TABLE IF EXISTS `sales_shift_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_shift_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `shift_id` int NOT NULL,
  `branch_id` int DEFAULT NULL,
  `user_id` int NOT NULL,
  `session_date` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `end_time` datetime(3) DEFAULT NULL,
  `expected_start_time` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expected_end_time` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `opening_balance` decimal(10,2) NOT NULL DEFAULT '0.00',
  `closing_balance` decimal(10,2) DEFAULT NULL,
  `expected_closing_balance` decimal(10,2) DEFAULT NULL,
  `cash_difference` decimal(10,2) DEFAULT NULL,
  `total_sales` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_cash` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_card` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_wallet` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_transfer` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_discount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_tax` decimal(10,2) NOT NULL DEFAULT '0.00',
  `transactions_count` int NOT NULL DEFAULT '0',
  `status` enum('open','closed','auto_closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `closed_by` int DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `closing_notes` text COLLATE utf8mb4_unicode_ci,
  `created_by` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_open_session` (`session_date`,`shift_id`,`branch_id`),
  KEY `sales_shift_sessions_branch_id_idx` (`branch_id`),
  KEY `sales_shift_sessions_user_id_idx` (`user_id`),
  KEY `sales_shift_sessions_status_idx` (`status`),
  KEY `sales_shift_sessions_shift_id_fkey` (`shift_id`),
  CONSTRAINT `sales_shift_sessions_shift_id_fkey` FOREIGN KEY (`shift_id`) REFERENCES `sales_shifts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

