CREATE TABLE `tbl_hdoor_emps` (
  `hodoor_id` int NOT NULL AUTO_INCREMENT,
  `member_code` int DEFAULT NULL,
  `member_id` int DEFAULT NULL,
  `action_date` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action_date_s` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hdoor_time` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dwam_hdoor_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `late_min` double DEFAULT NULL,
  `ensraf_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dwam_ensraf_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobaker_min` double DEFAULT NULL,
  `hdoor_user_id` int DEFAULT NULL,
  `ensraf_user_id` int DEFAULT NULL,
  `ttype` enum('hdoor','ensraf','Out') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `num_min` double DEFAULT NULL,
  `tasgel_type` enum('automatic','manual') COLLATE utf8mb4_unicode_ci DEFAULT 'automatic',
  `hdoor_img_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ensraf_img_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hdoor_lat` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hdoor_long` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ensraf_lat` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ensraf_long` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_hdoor_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_hdoor_user_id` int DEFAULT NULL,
  `second_dwam_hdoor_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_late_min` double DEFAULT NULL,
  `second_hdoor_img_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_hdoor_lat` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_hdoor_long` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_ensraf_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_ensraf_user_id` int DEFAULT NULL,
  `second_dwam_ensraf_time` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_mobaker_min` double DEFAULT NULL,
  `second_ensraf_img_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_ensraf_lat` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `second_ensraf_long` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `for_month` int DEFAULT NULL,
  `for_year` int DEFAULT NULL,
  `mobker_hdor` int DEFAULT '0',
  `ensraf_point` int DEFAULT NULL,
  `sheft_type` int NOT NULL,
  `branch_id_fk` int NOT NULL,
  `dwam_id_fk` int NOT NULL,
  PRIMARY KEY (`hodoor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=686 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
